from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent
base=json.loads((ROOT/'analysis/audio-timing.json').read_text(encoding='utf-8'))
groups=[
 ('قبل ما تبيع',[(0,'7 خطوات قبل ما تبيع','7'),(3.32,'تحمي حساباتك والداتا تاعك','تحمي'),(7.26,'يلا نبدأو بأول خطوة','أول')]),
 ('النسخة الاحتياطية',[(0,'أول حاجة: نسخة احتياطية','احتياطية'),(2.78,'التصاور والفيديوهات','التصاور'),(3.96,'الأرقام ومحادثات WhatsApp','WhatsApp'),(5.96,'اختار وين تحفظ النسخة','تحفظ'),(7.68,'Google Drive ولا iCloud','iCloud'),(9.18,'ولا تنقلهم للـ PC','PC'),(10.28,'النسخة وحدها ما تكفيش','ما تكفيش'),(12.14,'افتح الملفات وتأكد ترجعهم','افتح')]),
 ('أكواد التحقق',[(0,'الثانية بزاف ناس ينساوها','الثانية'),(2.22,'تستعمل Google Authenticator؟','Authenticator؟'),(3.84,'انقل الحسابات للتليفون الجديد','انقل'),(6.1,'كلمة السر + كود التحقق','كود التحقق'),(8.38,'طبقة حماية إضافية','حماية'),(10.56,'إذا ما نقلتش الأكواد…','ما نقلتش'),(12.08,'تقدر تخسر الدخول لحساباتك','الدخول'),(14.28,'2FA موضوع مهم بزاف','2FA'),(16.46,'نخصصله فيديو وحدو','فيديو')]),
 ('الأجهزة المرتبطة',[(0,'الساعة مربوطة بالتليفون القديم','الساعة'),(2.92,'افصلها بالطريقة الصحيحة','افصلها'),(5.24,'ونحّي ربط أجهزة Bluetooth','Bluetooth')]),
 ('حساب Google / Apple',[(0,'الحساب ما يبقاش في التليفون','الحساب'),(1.99,'Android: نحّي حساب Google','Google'),(5.85,'iPhone: اخرج من Apple Account','Apple Account'),(9.53,'وعطّل خدمة Find My','Find My')]),
 ('التطبيقات الحساسة',[(0,'خامس حاجة: التطبيقات الحساسة','الحساسة'),(1.98,'حساباتك وتطبيقات المراسلة','حساباتك'),(4.84,'دير déconnexion وين لازم','déconnexion'),(6.48,'من جهاز آخر: إعدادات الأمان','الأمان'),(9.58,'نحّي التليفون القديم من القائمة','القديم'),(12.72,'WhatsApp: قبل الفورماط','WhatsApp'),(13.86,'انقل الحساب والمحادثات للجديد','المحادثات')]),
 ('الفورماط',[(0,'درك فقط نروحو للفورماط','درك فقط'),(2.32,'Settings ثم اختيار المسح','Settings'),(3.78,'Factory Reset','Factory Reset'),(5.9,'خليه يكمل العملية','يكمل')]),
 ('التحقق الأخير',[(0,'تأكد من شاشة البداية','البداية'),(3.52,'وين تختار اللغة','اللغة'),(5.02,'هاذ الشاشة وحدها ما تكفيش','ما تكفيش'),(6.74,'تأكد ما بقاش مربوط بحسابك','بحسابك'),(10.16,'وما يطلبوش وقت التفعيل','التفعيل')]),
 ('جاهز للبيع',[(0,'هكذا تقدر تسلّمو للشاري','للشاري'),(2.22,'دير Save باش ما تنساش','Save')]),
]
segments=[]
for i,(clip,(name,phrases)) in enumerate(zip(base['clips'],groups)):
    end=clip['end']+(.8 if i==8 else 0)
    segments.append({**clip,'end':end,'step':i,'name':name,'phrases':[{'at':at,'until':phrases[j+1][0] if j+1<len(phrases) else end-clip['start'],'text':text,'accent':accent} for j,(at,text,accent) in enumerate(phrases)]})
data={'durationInFrames':3390,'audioDuration':base['duration'],'segments':segments}
(ROOT/'media/timeline-v2.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
print('V2 semantic timeline saved; all nine source clips preserved.')
